{"version":3,"file":"ucam-site-ui.mjs","names":[],"sources":["../../../projects/site-ui/src/lib/nucleo/classes.ts","../../../projects/site-ui/src/lib/avatar/avatar.ts","../../../projects/site-ui/src/lib/button/button.ts","../../../projects/site-ui/src/lib/nucleo/provedor.ts","../../../projects/site-ui/src/lib/icon/icon.ts","../../../projects/site-ui/src/lib/icon-chip/icon-chip.ts","../../../projects/site-ui/src/lib/section-heading/section-heading.ts","../../../projects/site-ui/src/lib/tag/tag.ts","../../../projects/site-ui/src/public-api.ts"],"sourcesContent":["/**
 * A lista de classes de uma peça: a raiz e um `raiz--mod` por modificador
 * verdadeiro. Os nomes vêm do contrato da peça; a lib nunca inventa classe.
 */
export function classesDe(raiz: string, ...mods: (string | false | null | undefined)[]): string {
  return [raiz, ...mods.filter((m): m is string => !!m).map((m) => `${raiz}--${m}`)].join(' ');
}

/** Devolve `valor` se estiver na lista do contrato; senão, o padrão. */
export function umDe<T extends string>(lista: readonly T[], padrao: T): (valor: unknown) => T {
  return (valor) => (lista.includes(valor as T) ? (valor as T) : padrao);
}
","import { Directive, computed, input } from '@angular/core';
import { classesDe, umDe } from '../nucleo/classes';

export type UcamSiteAvatarSize = 'sm' | 'md' | 'lg';
export type UcamSiteAvatarShape = 'person' | 'logo';

const TAMANHOS = ['sm', 'md', 'lg'] as const;
const FORMAS = ['person', 'logo'] as const;

/**
 * Avatar dos sites. Contrato: sites/spec/components/avatar.json.
 *
 * Com `name`, o avatar É a identificação: vira imagem com rótulo. Sem `name`,
 * o nome está escrito ao lado e o avatar é decorativo. As iniciais ou a
 * `<img>` são conteúdo do consumidor.
 */
@Directive({
  selector: '[ucamSiteAvatar]',
  host: {
    '[class]': 'classes()',
    '[attr.role]': 'rotulo() ? "img" : null',
    '[attr.aria-label]': 'rotulo()',
    '[attr.aria-hidden]': 'rotulo() ? null : "true"',
  },
})
export class UcamSiteAvatar {
  readonly size = input<UcamSiteAvatarSize, UcamSiteAvatarSize | null | undefined>('md', { transform: umDe(TAMANHOS, 'md') });
  readonly shape = input<UcamSiteAvatarShape, UcamSiteAvatarShape | null | undefined>('person', { transform: umDe(FORMAS, 'person') });
  readonly name = input<string | null | undefined>(null);

  /** O nome aparado, ou null quando não há o que anunciar. */
  protected readonly rotulo = computed(() => this.name()?.trim() || null);

  protected readonly classes = computed(() =>
    classesDe('ucam-site-avatar', this.size() !== 'md' && this.size(), this.shape() === 'logo' && 'logo'),
  );
}
","import { Directive, booleanAttribute, computed, input } from '@angular/core';
import { classesDe, umDe } from '../nucleo/classes';

export type UcamSiteButtonVariant = 'primary' | 'secondary' | 'ghost';
export type UcamSiteButtonSize = 'md' | 'lg';

const VARIANTES = ['primary', 'secondary', 'ghost'] as const;
const TAMANHOS = ['md', 'lg'] as const;

/**
 * Botão dos sites. Contrato: sites/spec/components/button.json.
 *
 * Diretiva sobre `<a>` ou `<button>`: nos sites o botão é quase sempre uma
 * âncora, e `href`, `routerLink`, `type` e `disabled` continuam nativos.
 */
@Directive({
  selector: 'a[ucamSiteButton], button[ucamSiteButton]',
  host: { '[class]': 'classes()' },
})
export class UcamSiteButton {
  // A ESCRITA é tipada pelo contrato: literal errado no template não compila. O
  // transform ainda cai no padrão para o que chega sem tipo ($any, JS, dado de CMS).
  readonly variant = input<UcamSiteButtonVariant, UcamSiteButtonVariant | null | undefined>('primary', { transform: umDe(VARIANTES, 'primary') });
  readonly size = input<UcamSiteButtonSize, UcamSiteButtonSize | null | undefined>('md', { transform: umDe(TAMANHOS, 'md') });
  readonly inverse = input(false, { transform: booleanAttribute });

  protected readonly classes = computed(() =>
    classesDe('ucam-site-btn', this.variant(), this.size() === 'lg' && 'lg', this.inverse() && 'inverse'),
  );
}
","import { InjectionToken, makeEnvironmentProviders, type EnvironmentProviders } from '@angular/core';

/**
 * Endereço do sprite de ícones. Vazio é o padrão e quer dizer "o sprite está
 * em linha na página": o <use> aponta para `#i-nome`. Com um endereço, aponta
 * para `endereço#i-nome`, que é como um site estático costuma servir o
 * arquivo de @ucam/site-css/icons/sprite.svg.
 */
export const UCAM_SITE_SPRITE = new InjectionToken<string>('UCAM_SITE_SPRITE', {
  providedIn: 'root',
  factory: () => '',
});

export interface UcamSiteOpcoes {
  sprite?: string;
}

export function provideUcamSite(opcoes: UcamSiteOpcoes = {}): EnvironmentProviders {
  return makeEnvironmentProviders([{ provide: UCAM_SITE_SPRITE, useValue: opcoes.sprite ?? '' }]);
}
","import { ChangeDetectionStrategy, Component, ViewEncapsulation, inject, input } from '@angular/core';
import { UCAM_SITE_SPRITE } from '../nucleo/provedor';

/**
 * Ícone do sprite compartilhado: `<svg ucamSiteIcon="arrowRight"></svg>`.
 *
 * Sempre decorativo (aria-hidden): nos sites o ícone acompanha um texto, e
 * quem precisa de nome acessível o põe no elemento que o hospeda.
 *
 * É COMPONENTE, com o <use> no template, e não diretiva que cria o nó por
 * Renderer2: nó criado fora do template não é hidratado. O servidor
 * serializava o <use>, o cliente acrescentava outro ao hidratar e, na troca
 * de ícone, o do servidor ficava órfão por baixo do novo (revisão de
 * 10/10/2026, medido: 2 <use> no servidor, 4 no cliente).
 */
@Component({
  selector: 'svg[ucamSiteIcon]',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: { class: 'ic', 'aria-hidden': 'true' },
  template: `@if (ucamSiteIcon(); as nome) {<svg:use [attr.href]="sprite + '#i-' + nome" />}`,
})
export class UcamSiteIcon {
  readonly ucamSiteIcon = input.required<string>();

  protected readonly sprite = inject(UCAM_SITE_SPRITE);
}
","import { Directive, computed, input } from '@angular/core';
import { classesDe, umDe } from '../nucleo/classes';

export type UcamSiteIconChipSize = 'md' | 'lg';
export type UcamSiteIconChipTone = 'brand' | 'neutral' | 'inverse';

const TAMANHOS = ['md', 'lg'] as const;
const TONS = ['brand', 'neutral', 'inverse'] as const;

/**
 * Pastilha de ícone. Contrato: sites/spec/components/icon-chip.json.
 * Decorativa: acompanha um título que está fora dela. O ícone é o
 * `<svg ucamSiteIcon>` que o consumidor põe dentro.
 */
@Directive({
  selector: '[ucamSiteIconChip]',
  host: { '[class]': 'classes()', 'aria-hidden': 'true' },
})
export class UcamSiteIconChip {
  readonly size = input<UcamSiteIconChipSize, UcamSiteIconChipSize | null | undefined>('md', { transform: umDe(TAMANHOS, 'md') });
  readonly tone = input<UcamSiteIconChipTone, UcamSiteIconChipTone | null | undefined>('brand', { transform: umDe(TONS, 'brand') });

  protected readonly classes = computed(() =>
    classesDe('ucam-site-icon-chip', this.size() === 'lg' && 'lg', this.tone() !== 'brand' && this.tone()),
  );
}
","import { ChangeDetectionStrategy, Component, Directive, ViewEncapsulation, booleanAttribute, computed, input } from '@angular/core';
import { classesDe, umDe } from '../nucleo/classes';

export type UcamSiteSectionHeadingAlign = 'start' | 'center';
export type UcamSiteSectionHeadingSize = 'section' | 'section-sm';

const ALINHAMENTOS = ['start', 'center'] as const;
const TAMANHOS = ['section', 'section-sm'] as const;

/**
 * Cabeçalho de seção. Contrato: sites/spec/components/section-heading.json.
 *
 * Componente de seletor de ATRIBUTO: o `<header>` (ou `<div>`) é do
 * consumidor e é a raiz do contrato, sem elemento hospedeiro no meio. O
 * título se chama `heading` porque `title` é a dica nativa do navegador.
 */
@Component({
  selector: 'header[ucamSiteSectionHeading], div[ucamSiteSectionHeading]',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: { '[class]': 'classes()' },
  template: `@if (eyebrow()?.trim(); as texto) {<p class="ucam-site-section-heading__eyebrow">{{ texto }}</p>}
@if (level() === 3) {<h3 class="ucam-site-section-heading__title">{{ heading() }}</h3>} @else {<h2 class="ucam-site-section-heading__title">{{ heading() }}</h2>}
@if (lede()?.trim(); as texto) {<p class="ucam-site-section-heading__lede">{{ texto }}</p>}
<ng-content />`,
})
export class UcamSiteSectionHeading {
  readonly heading = input.required<string>();
  readonly eyebrow = input<string | null | undefined>(null);
  readonly lede = input<string | null | undefined>(null);
  readonly align = input<UcamSiteSectionHeadingAlign, UcamSiteSectionHeadingAlign | null | undefined>('start', { transform: umDe(ALINHAMENTOS, 'start') });
  readonly size = input<UcamSiteSectionHeadingSize, UcamSiteSectionHeadingSize | null | undefined>('section', { transform: umDe(TAMANHOS, 'section') });
  readonly inverse = input(false, { transform: booleanAttribute });
  /** Nível do título: 2 por padrão, 3 quando a seção está dentro de outra. */
  readonly level = input<2 | 3, 2 | 3 | '2' | '3' | null | undefined>(2, { transform: (v) => (Number(v) === 3 ? 3 : 2) });

  protected readonly classes = computed(() =>
    classesDe(
      'ucam-site-section-heading',
      this.align() === 'center' && 'center',
      this.size() === 'section-sm' && 'sm',
      this.inverse() && 'inverse',
    ),
  );
}

/** A fileira de ações do cabeçalho de seção: `<div ucamSiteSectionHeadingAcoes>`. */
@Directive({
  selector: '[ucamSiteSectionHeadingAcoes]',
  host: { class: 'ucam-site-section-heading__acoes' },
})
export class UcamSiteSectionHeadingAcoes {}
","import { Directive, computed, input } from '@angular/core';
import { classesDe, umDe } from '../nucleo/classes';

export type UcamSiteTagTone = 'neutral' | 'brand' | 'info' | 'inverse';

const TONS = ['neutral', 'brand', 'info', 'inverse'] as const;

/**
 * Tag dos sites: uma palavra que classifica. Contrato: sites/spec/components/tag.json.
 * Nunca é clicável, então a diretiva não põe papel nem foco.
 */
@Directive({
  selector: '[ucamSiteTag]',
  host: { '[class]': 'classes()' },
})
export class UcamSiteTag {
  readonly tone = input<UcamSiteTagTone, UcamSiteTagTone | null | undefined>('neutral', { transform: umDe(TONS, 'neutral') });

  protected readonly classes = computed(() => classesDe('ucam-site-tag', this.tone() !== 'neutral' && this.tone()));
}
